export const getV1ConversionFromToRoute = createRoute({
  method: 'get',
  path: '/v1/conversion/{from}/{to}',
  tags: ['fx:conversion'],
  summary: 'Real-time Currency Conversion',
  description:
    'Get currency conversions using the latest market conversion rates. Note than you can convert in both directions. For example USD to CAD or CAD to USD.',
  operationId: 'RealTimeCurrencyConversion',
  request: {
    params: z.object({
      from: z
        .string()
        .openapi({
          param: {
            description: 'The "from" symbol of the pair.',
            example: 'AUD',
            in: 'path',
            name: 'from',
            required: true,
            schema: { type: 'string' },
          },
        }),
      to: z
        .string()
        .openapi({
          param: {
            description: 'The "to" symbol of the pair.',
            example: 'USD',
            in: 'path',
            name: 'to',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      amount: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            description: 'The amount to convert, with a decimal.',
            example: 100,
            in: 'query',
            name: 'amount',
            schema: { default: 1, type: 'number' },
            required: false,
          },
        }),
      precision: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.union([z.literal(0), z.literal(1), z.literal(2), z.literal(3), z.literal(4)]),
        )
        .default(2)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The decimal precision of the conversion. Defaults to 2 which is 2 decimal places accuracy.',
            example: 2,
            in: 'query',
            name: 'precision',
            schema: { default: 2, enum: [0, 1, 2, 3, 4], type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'The last tick for this currency pair, plus the converted amount for the requested amount.',
      content: {
        'application/json': {
          schema: z
            .object({
              converted: z.float64().openapi({ description: 'The result of the conversion.' }),
              from: z.string().openapi({ description: 'The "from" currency symbol.' }),
              initialAmount: z
                .float64()
                .openapi({
                  description: 'The amount to convert.',
                  'x-polygon-go-type': { name: '*float64' },
                }),
              last: z
                .object({
                  ask: z.float64().openapi({ description: 'The ask price.' }),
                  bid: z.float64().openapi({ description: 'The bid price.' }),
                  exchange: z
                    .int()
                    .openapi({
                      description:
                        'The exchange ID. See <a href="https://massive.com/docs/rest/forex/market-operations/exchanges" alt="Exchanges">Exchanges</a> for Massive\'s mapping of exchange IDs.',
                    }),
                  timestamp: z
                    .int()
                    .openapi({
                      description: 'The Unix millisecond timestamp.',
                      'x-polygon-go-type': {
                        name: 'IMilliseconds',
                        path: 'github.com/polygon-io/ptime',
                      },
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Contains the requested quote data for the specified forex currency pair.',
                  required: ['exchange', 'timestamp', 'ask', 'bid'],
                  'x-polygon-go-type': { name: 'LastQuoteCurrencies' },
                }),
              request_id: z
                .string()
                .openapi({ description: 'A request id assigned by the server.' }),
              status: z.string().openapi({ description: "The status of this request's response." }),
              symbol: z
                .string()
                .openapi({ description: 'The symbol pair that was evaluated from the request.' }),
              to: z.string().openapi({ description: 'The "to" currency symbol.' }),
            })
            .openapi({
              required: [
                'status',
                'request_id',
                'from',
                'to',
                'symbol',
                'initialAmount',
                'converted',
              ],
            }),
          example: {
            converted: 73.14,
            from: 'AUD',
            initialAmount: 100,
            last: { ask: 1.3673344, bid: 1.3672596, exchange: 48, timestamp: 1605555313000 },
            request_id: 'a73a29dbcab4613eeaf48583d3baacf0',
            status: 'success',
            symbol: 'AUD/USD',
            to: 'USD',
          },
        },
        'text/csv': {
          schema: z.string(),
          example: 'ask,bid,exchange,timestamp\n1.3673344,1.3672596,48,1605555313000\n',
        },
      },
    },
    default: { description: 'Unexpected error' },
  },
})

