export const getV1LastCryptoFromToRoute = createRoute({
  method: 'get',
  path: '/v1/last/crypto/{from}/{to}',
  tags: ['crypto:last:trade'],
  summary: 'Last Trade for a Crypto Pair',
  description: 'Get the last trade tick for a cryptocurrency pair.',
  operationId: 'LastTradeCrypto',
  request: {
    params: z.object({
      from: z
        .string()
        .openapi({
          param: {
            description: 'The "from" symbol of the pair.',
            example: 'BTC',
            in: 'path',
            name: 'from',
            required: true,
            schema: { type: 'string' },
          },
        }),
      to: z
        .string()
        .openapi({
          param: {
            description: 'The "to" symbol of the pair.',
            example: 'USD',
            in: 'path',
            name: 'to',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The last tick for this currency pair.',
      content: {
        'application/json': {
          schema: z
            .object({
              last: z
                .object({
                  conditions: z
                    .array(z.int32().openapi({ description: 'The condition code.' }))
                    .exactOptional()
                    .openapi({
                      description:
                        'A list of condition codes. See [Crypto Condition Codes](https://massive.com/docs/rest/crypto/market-operations/condition-codes) for what each code means.',
                      'x-polygon-go-type': { name: 'Int32Array' },
                    }),
                  exchange: z
                    .int()
                    .openapi({
                      description:
                        'The exchange that this crypto trade happened on.  \nSee <a href="https://massive.com/docs/rest/crypto/market-operations/exchanges">Exchanges</a> for a mapping of exchanges to IDs.',
                    }),
                  price: z
                    .float64()
                    .openapi({
                      description:
                        'The price of the trade. This is the actual dollar value per whole share of\nthis trade. A trade of 100 shares with a price of $2.00 would be worth a\ntotal dollar value of $200.00.',
                    }),
                  size: z
                    .float64()
                    .openapi({ description: 'The size of a trade (also known as volume).' }),
                  timestamp: z
                    .int()
                    .openapi({
                      description: 'The Unix millisecond timestamp.',
                      'x-polygon-go-type': {
                        name: 'IMilliseconds',
                        path: 'github.com/polygon-io/ptime',
                      },
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Contains the requested trade data for the specified cryptocurrency pair.',
                  required: ['exchange', 'price', 'size', 'timestamp'],
                  'x-polygon-go-type': { name: 'LastTradeCrypto' },
                }),
              request_id: z
                .string()
                .openapi({ description: 'A request id assigned by the server.' }),
              status: z.string().openapi({ description: "The status of this request's response." }),
              symbol: z
                .string()
                .openapi({ description: 'The symbol pair that was evaluated from the request.' }),
            })
            .openapi({ required: ['status', 'request_id', 'symbol'] }),
          example: {
            last: {
              conditions: [1],
              exchange: 4,
              price: 16835.42,
              size: 0.006909,
              timestamp: 1605560885027,
            },
            request_id: 'd2d779df015fe2b7fbb8e58366610ef7',
            status: 'success',
            symbol: 'BTC-USD',
          },
        },
        'text/csv': {
          schema: z.string(),
          example:
            'conditions,exchange,price,size,timestamp\n1,4,16835.42,0.006909,1605560885027\n',
        },
      },
    },
    default: { description: 'Unexpected error' },
  },
})

