export const getV2TicksStocksNbboTickerDateRoute = createRoute({
  method: 'get',
  path: '/v2/ticks/stocks/nbbo/{ticker}/{date}',
  tags: ['stocks:quotes'],
  summary: 'Quotes (NBBO)',
  description: 'Get NBBO quotes for a given ticker symbol on a specified date.\n',
  operationId: 'DeprecatedGetHistoricStocksQuotes',
  request: {
    params: z.object({
      ticker: z
        .string()
        .openapi({
          param: {
            description: 'The ticker symbol we want quotes for.',
            example: 'AAPL',
            in: 'path',
            name: 'ticker',
            required: true,
            schema: { type: 'string' },
          },
        }),
      date: z.iso
        .date()
        .openapi({
          param: {
            description: 'The date/day of the quotes to retrieve in the format YYYY-MM-DD.',
            example: '2020-10-14',
            in: 'path',
            name: 'date',
            required: true,
            schema: { format: 'date', type: 'string' },
          },
        }),
    }),
    query: z.object({
      timestamp: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The timestamp offset, used for pagination. This is the offset at which to start the results. Using the `timestamp` of the last result as the offset will give you the next page of results.\n',
            in: 'query',
            name: 'timestamp',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      timestampLimit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum timestamp allowed in the results.\n',
            in: 'query',
            name: 'timestampLimit',
            schema: { type: 'integer' },
            required: false,
          },
        }),
      reverse: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description: 'Reverse the order of the results.\n',
            example: true,
            in: 'query',
            name: 'reverse',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Limit the size of the response, max 50000 and default 5000.',
            example: 10,
            in: 'query',
            name: 'limit',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'A list of quotes.',
      content: {
        'application/json': {
          schema: z
            .object({
              db_latency: z
                .int()
                .exactOptional()
                .openapi({
                  description: 'Latency in milliseconds for the query results from the database.',
                }),
              results_count: z
                .int()
                .exactOptional()
                .openapi({ description: 'The total number of results for this request.' }),
              success: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Whether or not this query was executed successfully.' }),
              ticker: z
                .string()
                .exactOptional()
                .openapi({ description: 'The exchange symbol that this item is traded under.' }),
            })
            .openapi({ required: [] })
            .and(
              z
                .object({
                  results: z
                    .array(
                      z
                        .object({
                          T: z
                            .string()
                            .openapi({
                              description: 'The exchange symbol that this item is traded under.',
                            }),
                          f: z
                            .int()
                            .openapi({
                              description:
                                'The nanosecond accuracy TRF(Trade Reporting Facility) Unix Timestamp. This is the timestamp of when the trade reporting facility received this message.',
                            }),
                          q: z
                            .preprocess(
                              (val) =>
                                typeof val === 'number' && Number.isSafeInteger(val)
                                  ? BigInt(val)
                                  : typeof val === 'string' && /^-?\d+$/.test(val)
                                    ? BigInt(val)
                                    : val,
                              z.int64(),
                            )
                            .openapi({
                              type: 'integer',
                              format: 'int64',
                              description:
                                'The sequence number represents the sequence in which message events happened.\nThese are increasing and unique per ticker symbol, but will not always be\nsequential (e.g., 1, 2, 6, 9, 10, 11).\n',
                            }),
                          t: z
                            .int()
                            .openapi({
                              description:
                                'The nanosecond accuracy SIP Unix Timestamp. This is the timestamp of when the SIP received this message from the exchange which produced it.',
                            }),
                          y: z
                            .int()
                            .openapi({
                              description:
                                'The nanosecond accuracy Participant/Exchange Unix Timestamp. This is the timestamp of when the quote was actually generated at the exchange.',
                            }),
                        })
                        .openapi({ required: ['T', 't', 'y', 'f', 'q'] })
                        .and(
                          z
                            .object({
                              P: z.float64().openapi({ description: 'The ask price.' }),
                              S: z
                                .int()
                                .openapi({
                                  description:
                                    'The ask size. This represents the number of shares sellers are offering at the given ask price.',
                                }),
                              X: z
                                .int()
                                .openapi({
                                  description:
                                    'The ask exchange ID. See <a href="https://massive.com/docs/rest/stocks/market-operations/exchanges" alt="Exchanges">Exchanges</a> for Massive\'s mapping of exchange IDs.',
                                }),
                              c: z
                                .array(z.int().openapi({ description: 'The condition code.' }))
                                .openapi({
                                  description:
                                    'A list of condition codes. See [Stocks Condition Codes](https://massive.com/docs/rest/stocks/market-operations/condition-codes) for what each code means.',
                                }),
                              i: z
                                .array(z.int().openapi({ description: 'The indicator code.\n' }))
                                .openapi({
                                  description:
                                    'The indicators. For more information, see our glossary of [Conditions and\nIndicators](https://massive.com/glossary/conditions-indicators).\n',
                                }),
                              p: z.float64().openapi({ description: 'The bid price.' }),
                              s: z
                                .int()
                                .openapi({
                                  description:
                                    'The bid size. This represents the number of shares buyers are bidding for at the given bid price.',
                                }),
                              x: z
                                .int()
                                .openapi({
                                  description:
                                    'The bid exchange ID. See <a href="https://massive.com/docs/rest/stocks/market-operations/exchanges" alt="Exchanges">Exchanges</a> for Massive\'s mapping of exchange IDs.',
                                }),
                              z: z
                                .int()
                                .openapi({
                                  description:
                                    'There are 3 tapes which define which exchange the ticker is listed on. These are integers in our objects which represent the letter of the alphabet. Eg: 1 = A, 2 = B, 3 = C.\n* Tape A is NYSE listed securities\n* Tape B is NYSE ARCA / NYSE American\n* Tape C is NASDAQ\n',
                                }),
                            })
                            .openapi({ required: ['c', 'i', 'p', 's', 'x', 'P', 'S', 'X', 'z'] }),
                        ),
                    )
                    .exactOptional(),
                })
                .openapi({ required: [] }),
            ),
          example: {
            db_latency: 43,
            map: {
              P: { name: 'ask_price', type: 'float64' },
              S: { name: 'ask_size', type: 'int' },
              X: { name: 'ask_exchange', type: 'int' },
              c: { name: 'conditions', type: 'int' },
              f: { name: 'trf_timestamp', type: 'int64' },
              i: { name: 'indicators', type: 'int' },
              p: { name: 'bid_price', type: 'float64' },
              q: { name: 'sequence_number', type: 'int' },
              s: { name: 'bid_size', type: 'int' },
              t: { name: 'sip_timestamp', type: 'int64' },
              x: { name: 'bid_exchange', type: 'int' },
              y: { name: 'participant_timestamp', type: 'int64' },
              z: { name: 'tape', type: 'int' },
            },
            results: [
              {
                P: 0,
                S: 0,
                X: 0,
                c: [1],
                p: 102.7,
                q: 2060,
                s: 60,
                t: 1517562000065700400,
                x: 11,
                y: 1517562000065321200,
                z: 3,
              },
              {
                P: 0,
                S: 0,
                X: 0,
                c: [1],
                p: 170,
                q: 2061,
                s: 2,
                t: 1517562000065791500,
                x: 11,
                y: 1517562000065408300,
                z: 3,
              },
            ],
            results_count: 2,
            success: true,
            ticker: 'AAPL',
          },
        },
      },
    },
    default: { description: 'Unexpected error' },
  },
})

